// DUWOP Anymouse (@duwop/anymouse): the anonymous idea / bug / gripe box. Drop <Anymouse /> anywhere (a header, a
// Settings page); it opens a small dialog and POSTs { kind, text, page } as JSON to `endpoint`. The app's server
// answers that with sendAnymouse() from lib/anymouse-server.ts, which posts to the app's Discord thread.
// Nothing about the user is sent: no name, no account, no device.

import { Bug, Lightbulb, Mouse, Send, ThumbsDown } from "lucide-react";
import { type ReactNode, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";

export type AnymouseKind = "idea" | "bug" | "gripe";

const kinds: { id: AnymouseKind; label: string; Icon: typeof Bug }[] = [
  { id: "idea", label: "Idea", Icon: Lightbulb },
  { id: "bug", label: "Bug", Icon: Bug },
  { id: "gripe", label: "Gripe", Icon: ThumbsDown },
];

export function Anymouse({
  endpoint = "/api/anymouse",
  headers,
  children,
  className,
}: {
  endpoint?: string;
  /** Extra request headers, e.g. a CSRF token. The request always sends JSON with the browser's cookies. */
  headers?: Record<string, string>;
  /** The trigger's label. Default: a mouse icon and "Anymouse". */
  children?: ReactNode;
  className?: string;
}) {
  const [open, setOpen] = useState(false);
  const [kind, setKind] = useState<AnymouseKind>("idea");
  const [text, setText] = useState("");
  const [busy, setBusy] = useState(false);
  const [note, setNote] = useState<{ ok: boolean; text: string } | null>(null);

  const send = async (e: React.FormEvent) => {
    e.preventDefault();
    setBusy(true);
    setNote(null);
    try {
      const res = await fetch(endpoint, {
        method: "POST",
        credentials: "same-origin",
        headers: { "content-type": "application/json", ...headers },
        body: JSON.stringify({ kind, text: text.trim(), page: location.pathname }),
      });
      const body = (await res.json().catch(() => ({}))) as { error?: string };
      if (!res.ok) throw new Error(body.error ?? `couldn't send (${res.status})`);
      setText("");
      setNote({ ok: true, text: "Sent. Thanks, it's anonymous." });
    } catch (err) {
      setNote({ ok: false, text: (err as Error).message });
    } finally {
      setBusy(false);
    }
  };

  return (
    <Dialog
      open={open}
      onOpenChange={(o) => {
        setOpen(o);
        if (o) setNote(null);
      }}
    >
      <DialogTrigger asChild>
        <Button variant="outline" className={className}>
          {children ?? (
            <>
              <Mouse className="size-4" aria-hidden /> Anymouse
            </>
          )}
        </Button>
      </DialogTrigger>
      <DialogContent>
        <form onSubmit={send} className="grid gap-4">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Mouse className="size-5 text-primary" aria-hidden /> Anymouse
            </DialogTitle>
            <DialogDescription>An idea, a bug or a gripe. No name is sent.</DialogDescription>
          </DialogHeader>
          <div role="radiogroup" aria-label="Kind" className="grid grid-cols-3 gap-2">
            {kinds.map(({ id, label, Icon }) => (
              <button
                key={id}
                type="button"
                role="radio"
                aria-checked={kind === id}
                onClick={() => setKind(id)}
                className={cn(
                  "flex h-11 items-center justify-center gap-1.5 rounded-md border border-border text-sm text-muted-foreground transition-colors hover:text-foreground",
                  kind === id && "border-primary bg-primary text-primary-foreground hover:text-primary-foreground",
                )}
              >
                <Icon className="size-4" aria-hidden /> {label}
              </button>
            ))}
          </div>
          <Textarea
            aria-label="Your note"
            placeholder="What should we know?"
            className="min-h-32 text-base"
            maxLength={2000}
            value={text}
            onChange={(e) => setText(e.target.value)}
          />
          {note && (
            <p role="status" className={cn("text-sm", note.ok ? "text-muted-foreground" : "text-destructive")}>
              {note.text}
            </p>
          )}
          <DialogFooter>
            <Button type="submit" className="h-11" disabled={busy || !text.trim()}>
              <Send className="size-4" aria-hidden /> Send
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

// DUWOP Anymouse, server half (@duwop/anymouse). Posts a note from the <Anymouse /> box to Discord, into the app's
// own thread. One webhook can serve every app (it lives in the channel that holds the "AM - <App>" threads); each
// app only needs its thread id. Plain fetch, no framework: wire it into any server in three lines, e.g. Hono:
//
//   app.post("/api/anymouse", async (c) => {
//     const r = await sendAnymouse(await c.req.json(), { app: "Session Hub" });
//     return c.json(r.body, r.status);
//   });
//
// Settings come from the options, else the environment: ANYMOUSE_DISCORD_WEBHOOK and ANYMOUSE_THREAD_ID.
// Keep the webhook server-side only: anyone holding it can post to the channel.

export type AnymouseOptions = {
  /** Shown in the message footer, e.g. "Session Hub". */
  app: string;
  /** Discord webhook URL. Default: process.env.ANYMOUSE_DISCORD_WEBHOOK. */
  webhook?: string;
  /** The app's thread id. Default: process.env.ANYMOUSE_THREAD_ID. Empty = post in the channel itself. */
  thread?: string;
  /** Most notes accepted per 10 minutes (whole server). Default 10. */
  limit?: number;
};

export type AnymouseResult = { status: 200 | 400 | 429 | 502 | 503; body: { ok: true } | { error: string } };

const KINDS = { idea: "💡 Idea", bug: "🐛 Bug", gripe: "👎 Gripe" } as const;
const WINDOW = 10 * 60_000;
const recent: number[] = [];

export async function sendAnymouse(input: unknown, opts: AnymouseOptions): Promise<AnymouseResult> {
  const env = typeof process === "undefined" ? {} : process.env;
  const webhook = opts.webhook ?? env.ANYMOUSE_DISCORD_WEBHOOK ?? "";
  const thread = opts.thread ?? env.ANYMOUSE_THREAD_ID ?? "";
  if (!/^https:\/\/(discord|discordapp)\.com\/api\/webhooks\/\d+\/[\w-]+$/.test(webhook))
    return { status: 503, body: { error: "Anymouse isn't set up yet (no Discord webhook)" } };
  if (thread && !/^\d{15,22}$/.test(thread)) return { status: 503, body: { error: "Anymouse thread id isn't a Discord id" } };

  const b = (input ?? {}) as Record<string, unknown>;
  const kind = typeof b.kind === "string" && b.kind in KINDS ? (b.kind as keyof typeof KINDS) : "idea";
  const text = typeof b.text === "string" ? b.text.trim() : "";
  const page = typeof b.page === "string" ? b.page.slice(0, 200) : "";
  if (!text) return { status: 400, body: { error: "write something first" } };
  if (text.length > 2000) return { status: 400, body: { error: "keep it under 2000 characters" } };

  const now = Date.now();
  while (recent.length && recent[0] < now - WINDOW) recent.shift();
  if (recent.length >= (opts.limit ?? 10)) return { status: 429, body: { error: "lots of notes just now, try again in a few minutes" } };
  recent.push(now);

  const url = new URL(webhook);
  url.searchParams.set("wait", "true");
  if (thread) url.searchParams.set("thread_id", thread);
  try {
    const res = await fetch(url, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        username: "Anymouse",
        allowed_mentions: { parse: [] }, // a note saying @everyone pings no one
        embeds: [
          {
            title: KINDS[kind],
            description: text,
            footer: { text: page ? `${opts.app} · ${page}` : opts.app },
            timestamp: new Date(now).toISOString(),
          },
        ],
      }),
    });
    if (!res.ok) {
      console.error(`anymouse: Discord answered ${res.status}`);
      return { status: 502, body: { error: `Discord refused it (${res.status})` } };
    }
    return { status: 200, body: { ok: true } };
  } catch {
    return { status: 502, body: { error: "couldn't reach Discord" } };
  }
}
